// Module contrôleur, série 2 : français (fr2), mathématiques (ma2), histoire-géographie (hg2).
// Style du QCM contrôleur 2026 (accords, homophones, conjugaison, vocabulaire ; calculs sans calculatrice ; repères d'histoire et de géographie).

// --- Français ---
BANK.push(
// Orthographe d'usage
{id:"fr2-001",t:"fr",q:"Quel mot est correctement orthographié ?",o:["exorbitant","exhorbitant","exorbittant","exhorbitent"],a:0,e:"Exorbitant (excessif, de la famille d'« orbite ») ne prend pas de h, contrairement à « exhorter ».",s:"Banque français"},
{id:"fr2-002",t:"fr",q:"Quel mot est mal orthographié ?",o:["accueil","dilemne","occurrence","courrier"],a:1,e:"On écrit « dilemme », avec deux m et sans n.",s:"Banque français"},
{id:"fr2-003",t:"fr",q:"Quelle orthographe est correcte ?",o:["la rénumération des agents","la rémunérassion des agents","la rémunération des agents","la rénumérassion des agents"],a:2,e:"Rémunération (de la famille du latin munus, « présent ») : ré-mu-né-ration, et non « rénumération ».",s:"Banque français"},
{id:"fr2-004",t:"fr",q:"Quel mot est mal orthographié ?",o:["parallèle","succinct","exonération","aggression"],a:3,e:"Agression ne prend qu'un g ; c'est « aggraver » qui en prend deux.",s:"Banque français"},
{id:"fr2-005",t:"fr",q:"Quelle orthographe est correcte ?",o:["un avantage pécuniaire","un avantage pécunier","un avantage pécunière","un avantage pécuniair"],a:0,e:"Pécuniaire (relatif à l'argent) se termine par -aire au masculin comme au féminin.",s:"Banque français"},
{id:"fr2-006",t:"fr",q:"Complétez : « Les deux voisins ont réglé leur … à l'amiable. »",o:["différent","différend","différant","diffèrent"],a:1,e:"Le différend (nom) est un désaccord, un litige ; différent est l'adjectif et différant le participe présent de différer.",s:"Banque français"},
{id:"fr2-007",t:"fr",q:"Quel mot est correctement orthographié ?",o:["honnoraires","honorraires","honoraires","honnorraires"],a:2,e:"Honoraires, comme honorer et honorable, ne prend qu'un n, alors que honneur en prend deux.",s:"Banque français"},
// Accords
{id:"fr2-008",t:"fr",q:"Complétez : « La lettre et le colis sont … hier. » (arriver)",o:["arrivé","arrivée","arrivées","arrivés"],a:3,e:"Avec être, le participe s'accorde avec le sujet ; un nom féminin et un nom masculin donnent un accord au masculin pluriel.",s:"Banque français"},
{id:"fr2-009",t:"fr",q:"Quelle phrase est correcte ?",o:["Les réformes se sont succédé rapidement.","Les réformes se sont succédées rapidement.","Les réformes se sont succédés rapidement.","Les réformes se sont succédée rapidement."],a:0,e:"On succède à quelqu'un : « se » est COI, le participe reste invariable (comme dans « ils se sont parlé »).",s:"Banque français"},
{id:"fr2-010",t:"fr",q:"Quelle phrase est correcte ?",o:["Elles se sont souvenu de cette réunion.","Elles se sont souvenues de cette réunion.","Elles se sont souvenus de cette réunion.","Elles se sont souvenue de cette réunion."],a:1,e:"Se souvenir est un verbe essentiellement pronominal : le participe s'accorde avec le sujet.",s:"Banque français"},
{id:"fr2-011",t:"fr",q:"Quelle phrase est correctement accordée ?",o:["Les questions qu'elle s'est posé restent sans réponse.","Les questions qu'elle s'est posés restent sans réponse.","Les questions qu'elle s'est posées restent sans réponse.","Les questions qu'elle s'est posée restent sans réponse."],a:2,e:"« s' » est COI (à elle-même) ; le COD « que », mis pour « questions », est placé avant : accord au féminin pluriel.",s:"Banque français"},
{id:"fr2-012",t:"fr",q:"Quelle phrase est correcte ?",o:["Les maisons qu'ils ont faites construire sont vendues.","Les maisons qu'ils ont faits construire sont vendues.","Les maisons qu'ils ont faite construire sont vendues.","Les maisons qu'ils ont fait construire sont vendues."],a:3,e:"Le participe « fait » suivi d'un infinitif est toujours invariable.",s:"Banque français"},
{id:"fr2-013",t:"fr",q:"Complétez : « Les efforts qu'il a … pour terminer ce dossier ont été considérables. »",o:["fallu","fallus","fallut","falu"],a:0,e:"Falloir est un verbe impersonnel : son participe passé est toujours invariable.",s:"Banque français"},
{id:"fr2-014",t:"fr",q:"Quelle phrase est correcte ?",o:["Elle est sortie la poubelle.","Elle a sorti la poubelle.","Elle a sortie la poubelle.","Elle est sorti la poubelle."],a:1,e:"Employé avec un COD, sortir se conjugue avec avoir ; le COD placé après n'entraîne pas d'accord.",s:"Banque français"},
{id:"fr2-015",t:"fr",q:"Quelle phrase est correctement accordée ?",o:["Elle porte des chaussures marrons.","Elle porte des chaussures marronnes.","Elle porte des chaussures marron.","Elle porte des chaussure marron."],a:2,e:"Les adjectifs de couleur issus d'un nom (marron, orange, cerise…) sont invariables.",x:"Exceptions qui s'accordent : rose, mauve, fauve, pourpre, écarlate, incarnat.",s:"Banque français"},
{id:"fr2-016",t:"fr",q:"Quelle écriture est correcte ?",o:["des yeux bleus clairs","des yeux bleus clair","des yeux bleu clairs","des yeux bleu clair"],a:3,e:"Un adjectif de couleur composé (bleu clair, vert foncé) reste invariable.",s:"Banque français"},
{id:"fr2-017",t:"fr",q:"Quel groupe nominal est correctement accordé ?",o:["des foulards roses","des foulards oranges","des foulards marrons","des foulards bleus foncés"],a:0,e:"Rose fait partie des couleurs qui s'accordent ; orange et marron sont invariables, tout comme les couleurs composées (bleu foncé).",s:"Banque français"},
{id:"fr2-018",t:"fr",q:"Complétez : « Ces femmes sont … honteuses de leur erreur. »",o:["tout","toutes","toute","touts"],a:1,e:"Tout, adverbe, varie devant un adjectif féminin commençant par une consonne ou un h aspiré : toutes honteuses.",s:"Banque français"},
{id:"fr2-019",t:"fr",q:"Complétez : « Elle était … surprise par la réponse. »",o:["tout","toutes","toute","touts"],a:2,e:"Tout, adverbe (= tout à fait), varie devant un adjectif féminin commençant par une consonne ou un h aspiré : toute surprise. Devant une voyelle ou un h muet, il reste en principe invariable (tout étonnée).",x:"L'arrêté du 28 décembre 1976 admet aussi l'accord devant une voyelle ou un h muet (toute étonnée) ; devant une consonne, l'accord est obligatoire.",s:"Banque français"},
{id:"fr2-020",t:"fr",q:"Quelle phrase est correctement écrite ?",o:["Mêmes les plus prudents se sont trompés.","Ils poursuivent les même objectifs.","Elles ont vérifié les comptes elle-mêmes.","Ils ont vérifié les comptes eux-mêmes."],a:3,e:"Après un pronom personnel pluriel, même s'accorde et se lie par un trait d'union (eux-mêmes, elles-mêmes) ; adjectif placé devant le nom, il s'accorde aussi (les mêmes objectifs) ; adverbe (= aussi, jusqu'à), il est invariable (même les plus prudents).",x:"L'arrêté du 28 décembre 1976 tolère l'absence d'accord de même après un nom ou un pronom pluriel (eux-même) et l'omission du trait d'union (eux mêmes).",s:"Banque français"},
{id:"fr2-021",t:"fr",q:"Quelle écriture est correcte ?",o:["deux heures et demie","deux heures et demi","deux heures et demies","deux heure et demie"],a:0,e:"Placé après le nom, demi s'accorde en genre seulement : deux heures et demie. Placé devant, il est invariable : une demi-heure.",s:"Banque français"},
{id:"fr2-022",t:"fr",q:"Quelle phrase est correcte ?",o:["Il marche nus-pied dans le sable.","Il marche nu-pieds dans le sable.","Il marche nu-pied dans le sable.","Il marche pieds nu dans le sable."],a:1,e:"Devant le nom, nu est invariable et suivi d'un trait d'union (nu-pieds) ; après le nom, il s'accorde (pieds nus).",x:"L'arrêté du 28 décembre 1976 admet aussi l'accord de nu placé devant le nom (nus pieds).",s:"Banque français"},
// Nombres en lettres
{id:"fr2-023",t:"fr",q:"Comment écrit-on 380 en lettres ?",o:["trois cent quatre-vingt","trois cents quatre-vingt","trois cent quatre-vingts","trois cent quatres-vingts"],a:2,e:"Cent suivi d'un autre nombre ne prend pas de s ; quatre-vingts, en fin de nombre, en prend un ; quatre reste invariable.",x:"L'arrêté du 28 décembre 1976 tolère le s de cent même suivi d'un autre nombre (trois cents quatre-vingts) ; les rectifications de 1990 recommandent les traits d'union (trois-cent-quatre-vingts).",s:"Banque français"},
{id:"fr2-024",t:"fr",q:"Quelle écriture est correcte ?",o:["deux cent millions d'euros","deux cents million d'euros","deux cent million d'euros","deux cents millions d'euros"],a:3,e:"Million est un nom, pas un adjectif numéral : cent, multiplié et non suivi d'un nombre, prend un s, et million se met au pluriel.",s:"Banque français"},
{id:"fr2-025",t:"fr",q:"Comment écrit-on 80 000 en lettres ?",o:["quatre-vingt mille","quatres-vingt mille","quatre-vingts milles","quatre-vingt milles"],a:0,e:"Vingt suivi de mille (adjectif numéral) ne prend pas de s ; mille, adjectif numéral, est toujours invariable ; quatre aussi.",x:"L'arrêté du 28 décembre 1976 tolère quatre-vingts mille ; les rectifications de 1990 recommandent quatre-vingt-mille.",s:"Banque français"},
{id:"fr2-026",t:"fr",q:"Comment écrit-on 1 200 € en lettres sur un chèque ?",o:["mille deux cent euros","mille deux cents euros","milles deux cents euros","mille deux cents euro"],a:1,e:"Deux cents (multiplié, non suivi d'un nombre) ; mille invariable ; euros au pluriel.",s:"Banque français"},
// Homophones
{id:"fr2-027",t:"fr",q:"Complétez : « Il … appris … lire tout seul. »",o:["à / a","a / a","a / à","à / à"],a:2,e:"« a » (verbe avoir) peut être remplacé par « avait » ; « à » est une préposition.",s:"Banque français"},
{id:"fr2-028",t:"fr",q:"Complétez : « Je ne sais pas … il travaille, à Lyon … à Paris. »",o:["ou / où","ou / ou","où / où","où / ou"],a:3,e:"« Où » indique le lieu ; « ou » (= ou bien) marque une alternative.",s:"Banque français"},
{id:"fr2-029",t:"fr",q:"Complétez : « … dossier … trouve sur le bureau. »",o:["Ce / se","Se / ce","Ce / ce","Se / se"],a:0,e:"« Ce » est un déterminant démonstratif (ce dossier) ; « se » est le pronom du verbe pronominal se trouver.",s:"Banque français"},
{id:"fr2-030",t:"fr",q:"Complétez : « Il … trompé de bureau. »",o:["c'est","s'est","ses","sait"],a:1,e:"Se tromper est pronominal : il s'est trompé. « C'est » signifie « cela est ».",s:"Banque français"},
{id:"fr2-031",t:"fr",q:"Complétez : « Je pense … viendra demain. »",o:["quelle","quel","qu'elle","qu'elles"],a:2,e:"On peut dire « qu'il viendra » : c'est donc que + elle, au singulier.",s:"Banque français"},
{id:"fr2-032",t:"fr",q:"Complétez : « … soient vos arguments, la décision est prise. »",o:["Quelque","Quelques","Quel que","Quels que"],a:3,e:"Devant le verbe être au subjonctif, on écrit quel que en deux mots, accordé avec le sujet (arguments, masculin pluriel).",s:"Banque français"},
{id:"fr2-033",t:"fr",q:"Complétez : « … à moi, je préfère attendre. »",o:["Quant","Quand","Qu'en","Quan"],a:0,e:"« Quant à » signifie « en ce qui concerne » ; « quand » indique le temps.",s:"Banque français"},
{id:"fr2-034",t:"fr",q:"Complétez : « Il est parti … prévenir personne. »",o:["s'en","sans","cent","sang"],a:1,e:"Sans, préposition, marque l'absence ; « s'en » appartient à un verbe pronominal (il s'en va).",s:"Banque français"},
{id:"fr2-035",t:"fr",q:"Complétez : « C'est une décision … , prise après mûre réflexion. »",o:["censée","censé","sensée","sensé"],a:2,e:"Sensé = raisonnable, plein de bon sens (ici accordé avec « décision ») ; censé = supposé.",s:"Banque français"},
{id:"fr2-036",t:"fr",q:"Complétez : « Les travaux dureront plusieurs semaines, … plusieurs mois. »",o:["voir","voie","voix","voire"],a:3,e:"Voire (adverbe) = et même ; voir est le verbe.",s:"Banque français"},
{id:"fr2-037",t:"fr",q:"Complétez : « Pour réussir, il faudra travailler … . »",o:["davantage","d'avantage","d'avantages","davantages"],a:0,e:"Davantage (adverbe, invariable) = plus ; « d'avantage » = de profit, de bénéfice.",s:"Banque français"},
{id:"fr2-038",t:"fr",q:"Complétez : « Le dossier est … à être signé. »",o:["près","prêt","prés","prête"],a:1,e:"Prêt à (adjectif) = préparé, disposé ; près de (adverbe) = à proximité ou sur le point de.",s:"Banque français"},
{id:"fr2-039",t:"fr",q:"Complétez : « Il est arrivé … que prévu. »",o:["plutôt","plutot","plus tôt","plus-tôt"],a:2,e:"Plus tôt s'oppose à plus tard ; plutôt signifie « de préférence ».",s:"Banque français"},
{id:"fr2-040",t:"fr",q:"Quelle phrase est correcte ?",o:["On a jamais reçu cette lettre.","On à jamais reçu cette lettre.","On n'a jamais reçue cette lettre.","On n'a jamais reçu cette lettre."],a:3,e:"La négation exige « ne » : on n'a jamais (la liaison masque le n' à l'oral).",s:"Banque français"},
{id:"fr2-041",t:"fr",q:"Complétez : « … vous fassiez, faites-le bien. »",o:["Quoi que","Quoique","Quoiqu'","Quoi qu'"],a:0,e:"Quoi que (en deux mots) = quelle que soit la chose que ; quoique (en un mot) = bien que.",s:"Banque français"},
// Conjugaison
{id:"fr2-042",t:"fr",q:"Complétez : « Bien qu'il … raison, il n'a pas été écouté. »",o:["a","ait","aie","est"],a:1,e:"Bien que est suivi du subjonctif : qu'il ait (« aie » est la 1re personne).",s:"Banque français"},
{id:"fr2-043",t:"fr",q:"Complétez : « Je doute qu'il … venir à la réunion. »",o:["peut","pourra","puisse","pouvait"],a:2,e:"Le doute appelle le subjonctif : qu'il puisse.",s:"Banque français"},
{id:"fr2-044",t:"fr",q:"Complétez : « Chaque soir, après qu'il … parti, nous fermons le bureau. »",o:["soit","serait","sera","est"],a:3,e:"Après que introduit un fait accompli : il se construit avec l'indicatif (à l'inverse d'avant que, suivi du subjonctif).",s:"Banque français"},
{id:"fr2-045",t:"fr",q:"Complétez au passé simple : « Le roi … ses ennemis. » (vaincre)",o:["vainquit","vaincut","vainqua","vainquât"],a:0,e:"Vaincre au passé simple : je vainquis, il vainquit, ils vainquirent.",s:"Banque français"},
{id:"fr2-046",t:"fr",q:"Complétez au futur : « Je vous … le dossier demain. » (envoyer)",o:["envoierai","enverrai","envoirai","enverais"],a:1,e:"Envoyer a un futur irrégulier : j'enverrai, nous enverrons.",s:"Banque français"},
{id:"fr2-047",t:"fr",q:"Complétez : « Si tu venais, je … content. »",o:["serai","sera","serais","seras"],a:2,e:"Si + imparfait, puis conditionnel présent : je serais (avec un s).",s:"Banque français"},
{id:"fr2-048",t:"fr",q:"Quelle forme du futur est correcte ?",o:["nous courerons","nous courirons","nous courons","nous courrons"],a:3,e:"Courir (comme mourir) double le r au futur et au conditionnel : nous courrons. « Nous courons » est le présent.",s:"Banque français"},
{id:"fr2-049",t:"fr",q:"Quelle phrase est correctement écrite ?",o:["Vas-y vite !","Va-y vite !","Vas-i vite !","Va-z-y vite !"],a:0,e:"À l'impératif, « va » prend un s devant les pronoms y et en : vas-y (de même : penses-y, manges-en).",s:"Banque français"},
{id:"fr2-050",t:"fr",q:"Complétez : « Il a dit qu'il … le lendemain. »",o:["viendra","viendrait","vient","vienne"],a:1,e:"Concordance des temps : après un verbe au passé, un fait futur s'exprime au conditionnel présent (futur dans le passé).",s:"Banque français"},
{id:"fr2-051",t:"fr",q:"« Quand il eut terminé son rapport, il partit. » À quel temps est « eut terminé » ?",o:["Plus-que-parfait","Passé composé","Passé antérieur","Futur antérieur"],a:2,e:"Auxiliaire au passé simple + participe passé : passé antérieur, souvent associé au passé simple.",s:"Banque français"},
{id:"fr2-052",t:"fr",q:"Complétez au passé simple : « Ils … avoir raison. » (croire)",o:["croyèrent","croirent","crûrent","crurent"],a:3,e:"Croire : je crus, ils crurent. « Crûrent », avec un accent, est le passé simple de croître.",s:"Banque français"},
{id:"fr2-053",t:"fr",q:"Complétez : « C'est un travail … . »",o:["fatigant","fatiguant","fatiguent","fatigants"],a:0,e:"L'adjectif verbal s'écrit fatigant ; fatiguant est le participe présent (en le fatiguant).",s:"Banque français"},
// Grammaire
{id:"fr2-054",t:"fr",q:"Dans « Le dossier que tu m'as remis est complet », quelle est la nature de « que » ?",o:["Une conjonction de subordination","Un pronom relatif","Un pronom interrogatif","Un adverbe"],a:1,e:"Il reprend son antécédent « le dossier » et introduit une proposition subordonnée relative.",s:"Banque français"},
{id:"fr2-055",t:"fr",q:"Dans « Le contrôleur répond au contribuable », quelle est la fonction de « au contribuable » ?",o:["COD","Complément circonstanciel de lieu","COI","Attribut du sujet"],a:2,e:"On répond à quelqu'un : complément du verbe introduit par la préposition « à » et non déplaçable : COI.",s:"Banque français"},
{id:"fr2-056",t:"fr",q:"Dans « Cette mesure semble efficace », quelle est la fonction de « efficace » ?",o:["COD","Épithète","Complément du nom","Attribut du sujet"],a:3,e:"Après un verbe d'état (être, sembler, paraître, devenir…), l'adjectif est attribut du sujet.",s:"Banque français"},
{id:"fr2-057",t:"fr",q:"Dans « Le rapport a été rédigé par l'inspectrice », quelle est la fonction de « par l'inspectrice » ?",o:["Complément d'agent","COI","Complément circonstanciel de moyen","COD"],a:0,e:"À la voix passive, le complément d'agent désigne celui qui fait l'action ; à l'actif, il devient sujet (l'inspectrice a rédigé le rapport).",s:"Banque français"},
{id:"fr2-058",t:"fr",q:"Quelle phrase est à la voix passive ?",o:["Le dossier est arrivé hier.","Le dossier a été transmis hier.","Le dossier est sur le bureau.","Le dossier semble complet."],a:1,e:"Être + participe passé d'un verbe transitif (transmettre) : voix passive. « Est arrivé » est le passé composé actif d'arriver.",s:"Banque français"},
{id:"fr2-059",t:"fr",q:"Dans « Nous partirons dès qu'il arrivera », quelle est la nature de la proposition « dès qu'il arrivera » ?",o:["Subordonnée relative","Subordonnée complétive","Subordonnée circonstancielle de temps","Subordonnée circonstancielle de cause"],a:2,e:"Introduite par la locution « dès que », elle indique le moment de l'action principale.",s:"Banque français"},
// Vocabulaire et paronymes
{id:"fr2-060",t:"fr",q:"Complétez : « Le départ de la délégation est … : il aura lieu dans quelques minutes. »",o:["éminent","émanant","immanent","imminent"],a:3,e:"Imminent = qui va se produire très prochainement ; éminent = remarquable, supérieur.",s:"Banque français"},
{id:"fr2-061",t:"fr",q:"Complétez : « La … économique actuelle pèse sur les recettes fiscales. »",o:["conjoncture","conjecture","conjonction","conjuration"],a:0,e:"La conjoncture est la situation du moment ; une conjecture est une supposition.",s:"Banque français"},
{id:"fr2-062",t:"fr",q:"Quel mot désigne la violation d'une loi ou d'un règlement ?",o:["Une effraction","Une infraction","Une affliction","Une fraction"],a:1,e:"L'infraction est la violation d'une règle ; l'effraction est le bris d'une clôture ou d'une serrure (vol avec effraction).",s:"Banque français"},
{id:"fr2-063",t:"fr",q:"Que signifie « collusion » ?",o:["Un choc violent entre deux véhicules","Une conclusion tirée trop hâtivement","Une entente secrète au détriment d'un tiers","Un mélange confus de plusieurs idées"],a:2,e:"Ne pas confondre avec collision (choc).",s:"Banque français"},
{id:"fr2-064",t:"fr",q:"Que signifie « proscrire » ?",o:["Recommander un traitement","Rédiger par écrit","Différer dans le temps","Interdire, condamner"],a:3,e:"Proscrire = interdire ; prescrire = ordonner, recommander (en droit, la prescription éteint un droit par l'écoulement du temps).",s:"Banque français"},
{id:"fr2-065",t:"fr",q:"Quel verbe signifie « percevoir une somme due » ?",o:["Recouvrer","Recouvrir","Recourir","Ressourcer"],a:0,e:"Le comptable public est chargé de recouvrer l'impôt (le recouvrement) ; recouvrir signifie couvrir de nouveau.",s:"Banque français"},
{id:"fr2-066",t:"fr",q:"Que signifie « caduc » ?",o:["Particulièrement coûteux","Devenu sans effet, périmé","Rédigé en double exemplaire","Adopté à l'unanimité"],a:1,e:"Un acte caduc a perdu sa valeur juridique. Féminin : caduque.",s:"Banque français"},
{id:"fr2-067",t:"fr",q:"Quel est le synonyme de « corroborer » ?",o:["Contredire","Collaborer","Confirmer","Compliquer"],a:2,e:"Corroborer = confirmer, appuyer (un témoignage corrobore une déclaration).",s:"Banque français"},
{id:"fr2-068",t:"fr",q:"Que signifie « entériner » ?",o:["Retarder une décision","Annuler un acte","Enterrer un projet","Ratifier, rendre définitif"],a:3,e:"Entériner = approuver officiellement, consacrer (entériner une décision, un accord).",s:"Banque français"},
{id:"fr2-069",t:"fr",q:"Que signifie « nonobstant » ?",o:["Malgré","En conséquence","Par ailleurs","Afin de"],a:0,e:"Nonobstant, préposition du langage juridique, signifie malgré, en dépit de.",s:"Banque français"},
{id:"fr2-070",t:"fr",q:"Que signifie « péremptoire » ?",o:["Qui est facultatif","Qui n'admet pas de réplique","Qui est provisoire","Qui est hors d'usage"],a:1,e:"Un ton, un argument péremptoire coupe court à toute discussion. Ne pas confondre avec périmé.",s:"Banque français"},
{id:"fr2-071",t:"fr",q:"Quel est l'antonyme d'« exhaustif » ?",o:["Complet","Épuisant","Partiel","Détaillé"],a:2,e:"Exhaustif = qui traite un sujet à fond, complet ; son contraire est partiel.",s:"Banque français"},
{id:"fr2-072",t:"fr",q:"Qu'est-ce que la concussion ?",o:["Une indemnité versée à un salarié lors de son licenciement","Une entente secrète entre entreprises pour fixer les prix","Un discours solennel prononcé devant une assemblée","La perception par un agent public de sommes qu'il sait ne pas être dues"],a:3,e:"Infraction pénale visant les dépositaires de l'autorité publique (exiger ou percevoir un impôt ou une taxe indus, ou accorder une exonération illégale).",s:"Banque français"},
// Expressions
{id:"fr2-073",t:"fr",q:"Que signifie « avoir maille à partir avec quelqu'un » ?",o:["Avoir un différend avec lui","Partager ses biens avec lui","Partir en voyage avec lui","Lui devoir de l'argent"],a:0,e:"La maille était une petite pièce de monnaie impossible à partager (« partir ») : d'où la dispute.",s:"Banque français"},
{id:"fr2-074",t:"fr",q:"Que signifie « ménager la chèvre et le chou » ?",o:["Économiser sur toutes les dépenses","Ménager deux camps opposés sans prendre parti","Vivre à la campagne de ses propres récoltes","Agir avec brutalité envers ses adversaires"],a:1,e:"Chercher à ne mécontenter aucune des deux parties.",s:"Banque français"},
{id:"fr2-075",t:"fr",q:"Que signifie « avoir pignon sur rue » ?",o:["Habiter au rez-de-chaussée d'un immeuble","Être lourdement endetté auprès de ses fournisseurs","Être solidement établi, avoir une bonne réputation","Être en conflit permanent avec ses voisins"],a:2,e:"À l'origine, posséder une maison dont le pignon donnait sur la rue, signe d'aisance.",s:"Banque français"},
// Figures de style
{id:"fr2-076",t:"fr",q:"Dire « il nous a quittés » pour « il est mort » est :",o:["une hyperbole","une métaphore","une antithèse","un euphémisme"],a:3,e:"L'euphémisme atténue une réalité pénible ou choquante.",s:"Banque français"},
{id:"fr2-077",t:"fr",q:"« Va, je ne te hais point » (Corneille, Le Cid) est :",o:["une litote","une hyperbole","une anaphore","un pléonasme"],a:0,e:"La litote dit moins pour faire entendre plus : Chimène avoue ainsi son amour.",s:"Banque français"},
{id:"fr2-078",t:"fr",q:"Désigner Paris par « la Ville lumière » est :",o:["une métonymie","une périphrase","une comparaison","un oxymore"],a:1,e:"La périphrase remplace un mot par une expression de plusieurs mots qui le caractérise.",s:"Banque français"},
{id:"fr2-079",t:"fr",q:"Quelle expression est un pléonasme ?",o:["Descendre l'escalier","Remonter le temps","Monter en haut","Sortir de la salle"],a:2,e:"Le pléonasme répète inutilement une idée : on ne peut monter qu'en haut.",s:"Banque français"},
{id:"fr2-080",t:"fr",q:"Comment appelle-t-on la répétition d'un même mot en tête de phrases ou de vers successifs ?",o:["Une allitération","Une gradation","Un chiasme","Une anaphore"],a:3,e:"Exemple : « Rome, l'unique objet de mon ressentiment ! / Rome, à qui… » (Corneille, Horace).",s:"Banque français"},
// Pluriels
{id:"fr2-081",t:"fr",q:"Quel est le pluriel de « un procès-verbal » ?",o:["des procès-verbaux","des procès-verbals","des procès-verbal","des procès-verbales"],a:0,e:"Procès (invariable au pluriel) et verbal, adjectif en -al : verbaux.",s:"Banque français"},
{id:"fr2-082",t:"fr",q:"Quel pluriel est fautif ?",o:["des pneus","des genous","des landaus","des hiboux"],a:1,e:"Genou fait partie des sept noms en -ou qui prennent un x : bijou, caillou, chou, genou, hibou, joujou, pou.",s:"Banque français"},
{id:"fr2-083",t:"fr",q:"Quel est le pluriel de « un chef-d'œuvre » ?",o:["des chef-d'œuvres","des chefs-d'œuvres","des chefs-d'œuvre","des chef-d'œuvre"],a:2,e:"Seul le premier nom varie : des chefs (de l'œuvre).",s:"Banque français"},
// Ponctuation
{id:"fr2-084",t:"fr",q:"Quel signe de ponctuation introduit le plus souvent une énumération, une explication ou une citation ?",o:["Le point-virgule","Le point d'exclamation","La virgule","Les deux-points"],a:3,e:"Les deux-points annoncent ce qui suit : liste, explication, conséquence ou paroles rapportées.",s:"Banque français"}
);

// --- Mathématiques ---
BANK.push(
// Pourcentages
{id:"ma2-001",t:"math",q:"Un prix passe de 80 € à 92 €. Quel est le pourcentage d'augmentation ?",o:["15 %","12 %","13 %","20 %"],a:0,e:"(92 − 80) / 80 = 12 / 80 = 0,15, soit 15 %.",x:"Le taux se calcule toujours par rapport à la valeur de départ.",s:"Banque maths"},
{id:"ma2-003",t:"math",q:"Après une hausse de 25 %, un loyer s'élève à 750 €. Quel était le loyer avant la hausse ?",o:["550 €","562,50 €","600 €","625 €"],a:2,e:"750 / 1,25 = 600 €.",x:"Erreur classique : retirer 25 % de 750 € (562,50 €), alors que les 25 % portaient sur l'ancien loyer.",s:"Banque maths"},
{id:"ma2-004",t:"math",q:"Quelle baisse en pourcentage annule exactement une hausse de 25 % ?",o:["15 %","22,5 %","25 %","20 %"],a:3,e:"1 / 1,25 = 0,8 : il faut multiplier par 0,8, soit une baisse de 20 %.",s:"Banque maths"},
{id:"ma2-005",t:"math",q:"La population d'une commune passe de 2 000 à 1 700 habitants. Quelle est son évolution ?",o:["−15 %","−3 %","−17,6 %","−30 %"],a:0,e:"(1 700 − 2 000) / 2 000 = −300 / 2 000 = −0,15, soit −15 %.",s:"Banque maths"},
{id:"ma2-007",t:"math",q:"Un salaire de 2 000 € augmente de 3 %, puis de 2 %. Quel est le nouveau salaire ?",o:["2 100,00 €","2 102,00 €","2 101,20 €","2 106,00 €"],a:2,e:"2 000 × 1,03 = 2 060 ; 2 060 × 1,02 = 2 101,20 €.",s:"Banque maths"},
// TVA
{id:"ma2-008",t:"math",q:"Un article coûte 250 € HT. Avec une TVA à 20 %, quel est son prix TTC ?",o:["270 €","275 €","312,50 €","300 €"],a:3,e:"250 × 1,20 = 300 €.",s:"Banque maths"},
{id:"ma2-009",t:"math",q:"Un prix de 84 € TTC comprend une TVA à 20 %. Quel est le montant de la TVA ?",o:["14 €","16 €","16,80 €","70 €"],a:0,e:"HT = 84 / 1,2 = 70 € ; TVA = 84 − 70 = 14 €.",x:"84 × 0,2 = 16,80 € est faux : le taux s'applique au prix HT, pas au prix TTC.",s:"Banque maths"},
{id:"ma2-010",t:"math",q:"Un livre coûte 21,10 € TTC, TVA à 5,5 % comprise. Quel est son prix HT ?",o:["19,94 €","20,00 €","20,05 €","21,00 €"],a:1,e:"21,10 / 1,055 = 20,00 € (vérification : 20 × 1,055 = 21,10).",s:"Banque maths"},
{id:"ma2-011",t:"math",q:"Une facture comporte 3 articles à 40 € HT. Une remise de 10 % s'applique sur le total HT, puis la TVA à 20 %. Quel est le montant TTC ?",o:["126,00 €","132,00 €","129,60 €","144,00 €"],a:2,e:"120 × 0,9 = 108 € HT ; 108 × 1,2 = 129,60 € TTC.",s:"Banque maths"},
// Proportionnalité
{id:"ma2-012",t:"math",q:"5 photocopieurs identiques impriment 1 000 pages en 4 minutes. Combien de pages un seul photocopieur imprime-t-il en 10 minutes ?",o:["200","250","2 000","500"],a:3,e:"Un photocopieur : 1 000 / 5 = 200 pages en 4 min, soit 50 pages par minute ; en 10 min : 500 pages.",s:"Banque maths"},
{id:"ma2-013",t:"math",q:"6 agents traitent un stock de dossiers en 10 jours. Combien de jours faut-il à 4 agents travaillant au même rythme ?",o:["15 jours","6,7 jours","12 jours","20 jours"],a:0,e:"Le travail représente 6 × 10 = 60 jours-agent ; 60 / 4 = 15 jours (proportionnalité inverse).",s:"Banque maths"},
{id:"ma2-014",t:"math",q:"On partage 1 200 € entre deux personnes proportionnellement à 3 et 5. Combien reçoit la mieux servie ?",o:["600 €","750 €","720 €","800 €"],a:1,e:"1 200 / (3 + 5) = 150 € par part ; 5 × 150 = 750 € (et 3 × 150 = 450 €).",s:"Banque maths"},
// Vitesses, durées
{id:"ma2-015",t:"math",q:"Un cycliste parcourt 45 km en 1 h 30. Quelle est sa vitesse moyenne ?",o:["25 km/h","34,6 km/h","30 km/h","45 km/h"],a:2,e:"1 h 30 = 1,5 h ; 45 / 1,5 = 30 km/h.",x:"Piège : 1 h 30 n'est pas 1,3 h (45 / 1,3 ≈ 34,6).",s:"Banque maths"},
{id:"ma2-016",t:"math",q:"Combien de temps faut-il pour parcourir 210 km à 90 km/h ?",o:["2 h 10","2 h 30","2 h 33","2 h 20"],a:3,e:"210 / 90 = 2,333… h ; 0,333 h × 60 = 20 min : 2 h 20.",s:"Banque maths"},
{id:"ma2-017",t:"math",q:"Combien vaut 72 km/h en mètres par seconde ?",o:["20 m/s","7,2 m/s","12 m/s","259,2 m/s"],a:0,e:"72 km/h = 72 000 m en 3 600 s, soit 20 m/s (on divise par 3,6).",s:"Banque maths"},
{id:"ma2-018",t:"math",q:"Un train part à 8 h 45 et arrive à 10 h 57. Quelle est la durée du trajet ?",o:["1 h 52","2 h 12","2 h 22","2 h 02"],a:1,e:"De 8 h 45 à 10 h 45 : 2 h ; de 10 h 45 à 10 h 57 : 12 min. Total : 2 h 12.",s:"Banque maths"},
{id:"ma2-020",t:"math",q:"Deux villes sont distantes de 300 km. Deux voitures partent en même temps l'une vers l'autre, à 70 km/h et 80 km/h. Au bout de combien de temps se croisent-elles ?",o:["1 h 30","2 h 30","3 h","2 h"],a:3,e:"Elles se rapprochent de 70 + 80 = 150 km chaque heure : 300 / 150 = 2 h.",s:"Banque maths"},
// Échelles
{id:"ma2-021",t:"math",q:"Sur un plan au 1/200, une pièce mesure 2,5 cm sur 2 cm. Quelles sont ses dimensions réelles ?",o:["5 m × 4 m","0,5 m × 0,4 m","50 m × 40 m","25 m × 20 m"],a:0,e:"2,5 × 200 = 500 cm = 5 m ; 2 × 200 = 400 cm = 4 m.",s:"Banque maths"},
{id:"ma2-022",t:"math",q:"Deux villes distantes de 18 km sont représentées à 6 cm l'une de l'autre sur une carte. Quelle est l'échelle de la carte ?",o:["1/30 000","1/300 000","1/3 000","1/3 000 000"],a:1,e:"18 km = 1 800 000 cm ; 1 800 000 / 6 = 300 000. Échelle : 1/300 000.",s:"Banque maths"},
// Conversions
{id:"ma2-023",t:"math",q:"Combien de cm² y a-t-il dans 1 m² ?",o:["100 cm²","1 000 cm²","10 000 cm²","100 000 cm²"],a:2,e:"1 m = 100 cm, donc 1 m² = 100 × 100 = 10 000 cm².",s:"Banque maths"},
{id:"ma2-024",t:"math",q:"À combien de centilitres correspondent 3,5 litres ?",o:["0,35 cL","35 cL","3 500 cL","350 cL"],a:3,e:"1 L = 100 cL ; 3,5 × 100 = 350 cL.",s:"Banque maths"},
{id:"ma2-025",t:"math",q:"Combien de minutes représentent 0,45 heure ?",o:["27 min","45 min","4 min 30 s","2 min 42 s"],a:0,e:"0,45 × 60 = 27 min.",s:"Banque maths"},
{id:"ma2-026",t:"math",q:"Un terrain mesure 2,4 km². Combien cela fait-il de m² ?",o:["240 000 m²","2 400 000 m²","24 000 000 m²","24 000 m²"],a:1,e:"1 km² = 1 000 m × 1 000 m = 1 000 000 m² ; 2,4 km² = 2 400 000 m².",s:"Banque maths"},
// Fractions et puissances
{id:"ma2-027",t:"math",q:"Combien vaut 2/3 + 1/4 ?",o:["3/7","3/12","11/12","5/6"],a:2,e:"Au dénominateur commun 12 : 8/12 + 3/12 = 11/12.",s:"Banque maths"},
{id:"ma2-028",t:"math",q:"Combien vaut (5/6) ÷ (10/3) ?",o:["1/3","4","25/9","1/4"],a:3,e:"Diviser, c'est multiplier par l'inverse : 5/6 × 3/10 = 15/60 = 1/4.",s:"Banque maths"},
{id:"ma2-029",t:"math",q:"Quelle est la plus grande de ces fractions ?",o:["2/3","3/5","5/8","7/12"],a:0,e:"2/3 ≈ 0,667 ; 5/8 = 0,625 ; 3/5 = 0,6 ; 7/12 ≈ 0,583.",s:"Banque maths"},
{id:"ma2-030",t:"math",q:"Un héritage de 36 000 € est partagé : le premier héritier reçoit 1/3, le deuxième 1/4, le troisième le reste. Combien reçoit le troisième ?",o:["12 000 €","15 000 €","9 000 €","18 000 €"],a:1,e:"1/3 + 1/4 = 7/12 ; reste 5/12 ; 36 000 × 5/12 = 15 000 €.",s:"Banque maths"},
{id:"ma2-031",t:"math",q:"Combien vaut 2³ × 2⁴ ?",o:["2¹²","4⁷","2⁷","4¹²"],a:2,e:"On additionne les exposants : 2³ × 2⁴ = 2⁷ = 128.",s:"Banque maths"},
{id:"ma2-032",t:"math",q:"Quelle est l'écriture scientifique de 45 000 ?",o:["45 × 10³","0,45 × 10⁵","4,5 × 10³","4,5 × 10⁴"],a:3,e:"Écriture scientifique : a × 10ⁿ avec 1 ≤ a < 10. 45 000 = 4,5 × 10 000 = 4,5 × 10⁴.",s:"Banque maths"},
// Arithmétique
{id:"ma2-033",t:"math",q:"Quel est le PGCD de 84 et 126 ?",o:["42","21","14","6"],a:0,e:"84 = 2² × 3 × 7 ; 126 = 2 × 3² × 7 ; PGCD = 2 × 3 × 7 = 42.",s:"Banque maths"},
{id:"ma2-034",t:"math",q:"Deux navettes partent ensemble d'une gare, l'une toutes les 12 minutes, l'autre toutes les 18 minutes. Au bout de combien de temps repartiront-elles ensemble ?",o:["30 min","36 min","6 min","216 min"],a:1,e:"On cherche le PPCM de 12 et 18 : 12 = 2² × 3, 18 = 2 × 3², PPCM = 2² × 3² = 36 min.",s:"Banque maths"},
{id:"ma2-035",t:"math",q:"Avec 60 bonbons et 84 chocolats, on veut composer le plus grand nombre possible de sachets identiques en utilisant tout. Combien de sachets ?",o:["6","24","12","42"],a:2,e:"PGCD(60 ; 84) = 12 sachets, contenant chacun 5 bonbons et 7 chocolats.",s:"Banque maths"},
{id:"ma2-036",t:"math",q:"Lequel de ces nombres est divisible par 3 mais pas par 9 ?",o:["234","351","405","123"],a:3,e:"Somme des chiffres de 123 : 6, multiple de 3 mais pas de 9. Pour 234, 351 et 405, la somme vaut 9.",s:"Banque maths"},
{id:"ma2-037",t:"math",q:"Quelle est la décomposition en facteurs premiers de 360 ?",o:["2³ × 3² × 5","2² × 3² × 10","2³ × 3 × 15","2⁴ × 3 × 5"],a:0,e:"360 = 8 × 45 = 2³ × 3² × 5. 10 et 15 ne sont pas premiers ; 2⁴ × 3 × 5 = 240.",s:"Banque maths"},
{id:"ma2-038",t:"math",q:"Lequel de ces nombres n'est pas premier ?",o:["83","91","89","97"],a:1,e:"91 = 7 × 13. Les trois autres sont premiers.",s:"Banque maths"},
// Équations et inéquations
{id:"ma2-039",t:"math",q:"Résolvez : 5x − 7 = 2x + 8",o:["x = 1/3","x = 3","x = 5","x = 15"],a:2,e:"5x − 2x = 8 + 7, soit 3x = 15, donc x = 5.",s:"Banque maths"},
{id:"ma2-040",t:"math",q:"Résolvez : 2(x + 3) = 4x − 2",o:["x = 2","x = −4","x = 8","x = 4"],a:3,e:"2x + 6 = 4x − 2, soit 8 = 2x, donc x = 4.",s:"Banque maths"},
{id:"ma2-041",t:"math",q:"Résolvez le système : 2x + y = 11 et x − y = 1",o:["x = 4, y = 3","x = 3, y = 5","x = 5, y = 1","x = 2, y = 7"],a:0,e:"En additionnant les deux équations : 3x = 12, x = 4, puis y = x − 1 = 3.",s:"Banque maths"},
{id:"ma2-042",t:"math",q:"Un groupe de 10 personnes paie 76 € de billets : 10 € par adulte et 6 € par enfant. Combien y a-t-il d'adultes ?",o:["3","4","5","6"],a:1,e:"a + e = 10 et 10a + 6e = 76 ; 10a + 6(10 − a) = 76, soit 4a = 16, a = 4 (et 6 enfants).",s:"Banque maths"},
{id:"ma2-043",t:"math",q:"Résolvez l'inéquation : 3x − 4 > 11",o:["x < 5","x > 7/3","x > 5","x > 15"],a:2,e:"3x > 15, donc x > 5 (on divise par 3, positif : le sens ne change pas).",s:"Banque maths"},
{id:"ma2-044",t:"math",q:"Quelles sont les solutions de (x − 2)(x + 5) = 0 ?",o:["x = −2 ou x = 5","x = 2 seulement","x = 2 ou x = 5","x = 2 ou x = −5"],a:3,e:"Un produit est nul si l'un des facteurs est nul : x − 2 = 0 ou x + 5 = 0.",s:"Banque maths"},
// Fonctions
{id:"ma2-045",t:"math",q:"Soit f(x) = 3x − 2. Combien vaut f(4) ?",o:["10","12","14","−2"],a:0,e:"f(4) = 3 × 4 − 2 = 10.",s:"Banque maths"},
{id:"ma2-046",t:"math",q:"Quel est le coefficient directeur de la droite passant par A(1 ; 3) et B(3 ; 7) ?",o:["1/2","2","4","5"],a:1,e:"(yB − yA) / (xB − xA) = (7 − 3) / (3 − 1) = 2.",s:"Banque maths"},
{id:"ma2-047",t:"math",q:"Une fonction affine f vérifie f(0) = 5 et f(2) = 1. Quelle est son expression ?",o:["f(x) = 2x + 5","f(x) = 5x − 2","f(x) = −2x + 5","f(x) = −4x + 5"],a:2,e:"b = f(0) = 5 ; a = (1 − 5) / (2 − 0) = −2 ; f(x) = −2x + 5.",s:"Banque maths"},
{id:"ma2-048",t:"math",q:"Un loueur propose la formule A (30 € + 0,20 € par km) ou la formule B (0,50 € par km). Au-delà de quelle distance la formule A devient-elle la moins chère ?",o:["60 km","150 km","200 km","100 km"],a:3,e:"30 + 0,2d < 0,5d ⟺ 30 < 0,3d ⟺ d > 100 km. À 100 km, les deux coûtent 50 €.",s:"Banque maths"},
{id:"ma2-049",t:"math",q:"Quelle est la dérivée de f(x) = x² + 3x − 1 ?",o:["2x + 3","x + 3","2x + 2","2x − 1"],a:0,e:"(x²)' = 2x ; (3x)' = 3 ; la dérivée d'une constante est nulle.",s:"Banque maths"},
{id:"ma2-050",t:"math",q:"Quelle est la dérivée de f(x) = 4x³ ?",o:["4x²","12x²","12x³","x⁴"],a:1,e:"(xⁿ)' = n xⁿ⁻¹ : 4 × 3x² = 12x².",s:"Banque maths"},
{id:"ma2-051",t:"math",q:"Pour quelle valeur de x la fonction f(x) = x² − 6x + 1 atteint-elle son minimum ?",o:["x = −3","x = 1","x = 3","x = 6"],a:2,e:"f'(x) = 2x − 6 s'annule en x = 3 ; f' est négative avant et positive après : f est décroissante puis croissante, minimum en 3.",s:"Banque maths"},
// Statistiques
{id:"ma2-052",t:"math",q:"Quelle est la moyenne de la série 8 – 12 – 15 – 9 – 11 ?",o:["10","10,5","12","11"],a:3,e:"(8 + 12 + 15 + 9 + 11) / 5 = 55 / 5 = 11.",s:"Banque maths"},
{id:"ma2-053",t:"math",q:"Un candidat obtient 10 (coefficient 3), 14 (coefficient 2) et 16 (coefficient 1). Quelle est sa moyenne ?",o:["≈ 12,33","12","13","≈ 13,33"],a:0,e:"(30 + 28 + 16) / 6 = 74 / 6 ≈ 12,33.",x:"Sans tenir compte des coefficients, on trouverait 40 / 3 ≈ 13,33.",s:"Banque maths"},
{id:"ma2-054",t:"math",q:"Quelle est la médiane de la série 5 – 9 – 2 – 14 – 7 – 11 ?",o:["7","8","9","8,5"],a:1,e:"Série classée : 2, 5, 7, 9, 11, 14. Six valeurs : médiane = (7 + 9) / 2 = 8.",x:"Il faut toujours classer la série avant de chercher la médiane.",s:"Banque maths"},
{id:"ma2-055",t:"math",q:"Un salarié a gagné 1 800 € par mois pendant 4 mois, puis 2 100 € par mois pendant 8 mois. Quel est son salaire mensuel moyen sur l'année ?",o:["1 950 €","2 025 €","2 000 €","2 050 €"],a:2,e:"(4 × 1 800 + 8 × 2 100) / 12 = (7 200 + 16 800) / 12 = 24 000 / 12 = 2 000 €.",s:"Banque maths"},
{id:"ma2-057",t:"math",q:"Quel est le premier quartile de la série 2 – 4 – 4 – 7 – 8 – 10 – 12 – 15 ?",o:["4","2","5,5","7,5"],a:0,e:"8 valeurs ; 8 × 0,25 = 2 : Q1 est la 2e valeur de la série classée, soit 4.",x:"Q1 est la plus petite valeur telle qu'au moins 25 % des données lui soient inférieures ou égales. 7,5 est la médiane.",s:"Banque maths"},
{id:"ma2-058",t:"math",q:"Dans une entreprise, 40 % des salariés sont des femmes ; 25 % des femmes et 30 % des hommes sont cadres. Quelle est la proportion de cadres ?",o:["27,5 %","28 %","30 %","55 %"],a:1,e:"0,40 × 0,25 + 0,60 × 0,30 = 0,10 + 0,18 = 0,28, soit 28 %.",s:"Banque maths"},
// Probabilités
{id:"ma2-059",t:"math",q:"On lance un dé équilibré à six faces. Quelle est la probabilité d'obtenir un nombre premier ?",o:["1/3","2/3","1/2","5/6"],a:2,e:"Les nombres premiers de 1 à 6 sont 2, 3 et 5 (1 n'est pas premier) : 3/6 = 1/2.",s:"Banque maths"},
{id:"ma2-062",t:"math",q:"On tire une carte d'un jeu de 32 cartes. Quelle est la probabilité de tirer un roi ou un cœur ?",o:["1/8","11/32","3/8","1/32"],a:1,e:"4 rois + 8 cœurs − 1 roi de cœur compté deux fois = 11 cartes : 11/32.",s:"Banque maths"},
{id:"ma2-063",t:"math",q:"Une urne contient 3 boules blanches et 2 noires. On tire deux boules successivement avec remise. Quelle est la probabilité d'obtenir deux boules blanches ?",o:["6/25","3/10","9/25","3/5"],a:2,e:"Tirages indépendants : 3/5 × 3/5 = 9/25.",x:"Sans remise, on aurait 3/5 × 2/4 = 3/10.",s:"Banque maths"},
// Intérêts
{id:"ma2-064",t:"math",q:"On place 1 000 € à 2 % par an à intérêts composés. De quel capital dispose-t-on au bout de 2 ans ?",o:["1 020,00 €","1 040,00 €","1 041,00 €","1 040,40 €"],a:3,e:"1 000 × 1,02² = 1 000 × 1,0404 = 1 040,40 €.",x:"À intérêts simples, on aurait 1 040 € : les intérêts composés produisent eux-mêmes des intérêts.",s:"Banque maths"},
{id:"ma2-065",t:"math",q:"Un capital placé à intérêts simples au taux annuel de 4 % rapporte 240 € en 18 mois. Quel est ce capital ?",o:["4 000 €","3 600 €","6 000 €","9 600 €"],a:0,e:"C × 0,04 × 1,5 = 240, donc C = 240 / 0,06 = 4 000 €.",s:"Banque maths"},
{id:"ma2-066",t:"math",q:"À intérêts simples au taux annuel de 5 %, en combien de temps un capital double-t-il ?",o:["10 ans","20 ans","14 ans","25 ans"],a:1,e:"Il faut gagner 100 % du capital, à raison de 5 % par an : 100 / 5 = 20 ans.",s:"Banque maths"},
// Géométrie
{id:"ma2-067",t:"math",q:"Un triangle rectangle a une hypoténuse de 13 cm et un côté de l'angle droit de 5 cm. Combien mesure l'autre côté ?",o:["8 cm","10 cm","12 cm","18 cm"],a:2,e:"Pythagore : 13² − 5² = 169 − 25 = 144, et √144 = 12 cm.",s:"Banque maths"},
{id:"ma2-068",t:"math",q:"Lequel de ces triangles, dont on donne les longueurs des côtés, est rectangle ?",o:["4 ; 5 ; 6","6 ; 7 ; 9","7 ; 8 ; 11","5 ; 12 ; 13"],a:3,e:"Réciproque de Pythagore : 5² + 12² = 25 + 144 = 169 = 13².",s:"Banque maths"},
{id:"ma2-069",t:"math",q:"Quelle est l'aire d'un disque de 5 cm de rayon (π ≈ 3,14) ?",o:["78,5 cm²","15,7 cm²","31,4 cm²","157 cm²"],a:0,e:"π × r² = 3,14 × 25 = 78,5 cm². (31,4 cm est son périmètre.)",s:"Banque maths"},
{id:"ma2-070",t:"math",q:"Deux angles d'un triangle mesurent 47° et 68°. Combien mesure le troisième ?",o:["55°","65°","75°","115°"],a:1,e:"La somme des angles d'un triangle vaut 180° : 180 − 47 − 68 = 65°.",s:"Banque maths"},
{id:"ma2-071",t:"math",q:"Combien de litres contient un aquarium de 50 cm × 40 cm × 25 cm ?",o:["5 L","500 L","50 L","5 000 L"],a:2,e:"50 × 40 × 25 = 50 000 cm³ ; 1 L = 1 000 cm³, soit 50 L.",s:"Banque maths"},
{id:"ma2-072",t:"math",q:"Dans un triangle ABC, M est sur [AB] et N sur [AC], avec (MN) parallèle à (BC). AM = 3 cm, AB = 9 cm et BC = 12 cm. Combien mesure MN ?",o:["3 cm","6 cm","8 cm","4 cm"],a:3,e:"Thalès : MN / BC = AM / AB = 3/9 = 1/3, donc MN = 12 / 3 = 4 cm.",s:"Banque maths"},
{id:"ma2-073",t:"math",q:"Quel est le volume d'un cylindre de 2 cm de rayon et 10 cm de hauteur (π ≈ 3,14) ?",o:["125,6 cm³","62,8 cm³","251,2 cm³","40 cm³"],a:0,e:"π × r² × h = 3,14 × 4 × 10 = 125,6 cm³.",s:"Banque maths"},
{id:"ma2-074",t:"math",q:"Quelle est la somme des angles intérieurs d'un hexagone convexe ?",o:["540°","720°","360°","1 080°"],a:1,e:"Un polygone à n côtés : (n − 2) × 180°. Pour n = 6 : 4 × 180 = 720°.",s:"Banque maths"},
// Problèmes concrets
{id:"ma2-075",t:"math",q:"Un salarié perçoit 1 850 € net par mois et un treizième mois. Quel est son revenu net annuel ?",o:["22 200 €","23 125 €","24 050 €","25 900 €"],a:2,e:"13 × 1 850 = 24 050 €.",s:"Banque maths"},
{id:"ma2-076",t:"math",q:"Une facture de 450 € bénéficie d'une remise de 10 %, puis d'un escompte de 2 % pour paiement comptant. Quel montant reste à payer ?",o:["396,00 €","400,00 €","405,00 €","396,90 €"],a:3,e:"450 × 0,90 = 405 € ; 405 × 0,98 = 396,90 €.",x:"Les réductions successives se multiplient : appliquer 12 % d'un coup donnerait 396 €.",s:"Banque maths"},
{id:"ma2-077",t:"math",q:"Un agent payé 15 € de l'heure travaille 35 heures normales et 4 heures supplémentaires majorées de 25 %. Combien gagne-t-il cette semaine ?",o:["600 €","585 €","610 €","645 €"],a:0,e:"35 × 15 = 525 € ; heure majorée : 15 × 1,25 = 18,75 € ; 4 × 18,75 = 75 €. Total : 600 €.",s:"Banque maths"},
{id:"ma2-078",t:"math",q:"Un ménage dispose de 2 400 € par mois. Il consacre 30 % au logement et 1/6 à l'alimentation. Combien lui reste-t-il ?",o:["1 120 €","1 280 €","1 320 €","1 480 €"],a:1,e:"Logement : 720 € ; alimentation : 400 € ; reste : 2 400 − 720 − 400 = 1 280 €.",s:"Banque maths"},
{id:"ma2-079",t:"math",q:"Un commerçant achète un article 120 € et le revend 150 €. Quel est son taux de marge (marge rapportée au coût d'achat) ?",o:["20 %","30 %","25 %","80 %"],a:2,e:"Marge : 30 € ; 30 / 120 = 25 %. Rapportée au prix de vente (taux de marque), elle ferait 30 / 150 = 20 %.",s:"Banque maths"},
{id:"ma2-080",t:"math",q:"Un impôt fictif est calculé par tranches : 0 % jusqu'à 10 000 €, 10 % de 10 000 € à 30 000 €, 30 % au-delà. Combien paie-t-on pour un revenu de 40 000 € ?",o:["4 000 €","10 000 €","12 000 €","5 000 €"],a:3,e:"0 € sur la 1re tranche ; 10 % × 20 000 = 2 000 € ; 30 % × 10 000 = 3 000 €. Total : 5 000 €.",x:"Chaque taux ne s'applique qu'à la fraction du revenu comprise dans sa tranche, comme pour le barème de l'impôt sur le revenu.",s:"Banque maths"}
);

